%dw 2.0
output application/json
---
{
    id: uuid(),
    name: payload.name default "New Collection",
    parentId: payload.parentId default null,
    workspaceId: payload.workspaceId default null,
    variables: {}
}

db:update.db:input-parameters:
#[{
                id: attributes.uriParams.collectionId,
                parentId: payload.parentId default null
            }]

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    id: uuid(),
    collectionId: attributes.uriParams.collectionId,
    name: payload.name default "New Request",
    description: "",
    preRequest: [],
    request: {
        method: "GET",
        url: "",
        params: [],
        headers: [],
        bodyMode: "raw-json",
        // Built via a Unicode escape rather than writing the dollar-sign character itself
        // anywhere in this source file — Mule's own config-property resolver flags a literal
        // dollar sign even alone (not just paired with a brace) and tries to resolve it as a
        // config property, which fails for anything that isn't one. The escape below produces
        // the same character at runtime without the glyph itself ever appearing in the deployed
        // source for that scanner to find.
        body: "\u0024{body}"
    },
    postResponse: [],
    inputDataSets: []
}

db:update.db:input-parameters:
#[{
                id: attributes.uriParams.requestId,
                collectionId: payload.collectionId default null
            }]

ee:message.ee:set-payload:
%dw 2.0
import * from dw::core::Arrays
output application/json
var workspaceId = payload.workspaceId default null
var parentId = payload.parentId default null
var mergeIntoParent = payload.mergeIntoParent default false
var roots = payload.roots default []

fun reqRow(r, colId) = {
    id: uuid(),
    collectionId: colId,
    name: r.name default "Request",
    description: r.description default "",
    preRequestJson: write(r.preRequest default [], "application/json"),
    requestJson: write(r.request default {}, "application/json"),
    postResponseJson: write(r.postResponse default [], "application/json"),
    inputDataSetsJson: write(r.inputDataSets default [], "application/json")
}

// Creates a new collection row for `node` itself (under `pId`), plus everything nested in it.
fun flattenNew(node, pId) = do {
    var colId = uuid()
    var col = {
        id: colId, name: node.name default "Imported", parentId: pId, workspaceId: workspaceId,
        variablesJson: write(node.variables default {}, "application/json")
    }
    var reqs = (node.requests default []) map ((r) -> reqRow(r, colId))
    var children = (node.folders default []) map ((f) -> flattenNew(f, colId))
    ---
    {
        collections: [col] ++ flatten(children map ((c) -> c.collections)),
        requests: reqs ++ flatten(children map ((c) -> c.requests))
    }
}

// mergeIntoParent case — `node`'s own requests/folders attach directly under the EXISTING
// `pId`, no new collection row for `node` itself (its sub-folders still get real new rows).
fun flattenMerged(node, pId) = do {
    var reqs = (node.requests default []) map ((r) -> reqRow(r, pId))
    var children = (node.folders default []) map ((f) -> flattenNew(f, pId))
    ---
    {
        collections: flatten(children map ((c) -> c.collections)),
        requests: reqs ++ flatten(children map ((c) -> c.requests))
    }
}

var results = if (mergeIntoParent and parentId != null and sizeOf(roots) == 1)
    [flattenMerged(roots[0], parentId)]
else
    roots map ((r) -> flattenNew(r, parentId))
---
{
    collections: flatten(results map ((r) -> r.collections)),
    requests: flatten(results map ((r) -> r.requests))
}
